/// This command is used to start an authorization session using alternative methods of
/// establishing the session key (sessionKey). The session key is then used to derive
/// values used for authorization and for encrypting parameters.
#[derive(Debug, Clone)]
pub struct TPM2_StartAuthSession_REQUEST {
    /// Handle of a loaded decrypt key used to encrypt salt
    /// may be TPM_RH_NULL
    /// Auth Index: None
    pub tpmKey: TPM_HANDLE,

    /// Entity providing the authValue
    /// may be TPM_RH_NULL
    /// Auth Index: None
    pub bind: TPM_HANDLE,

    /// Initial nonceCaller, sets nonceTPM size for the session
    /// shall be at least 16 octets
    pub nonceCaller: Vec<u8>,

    /// Value encrypted according to the type of tpmKey
    /// If tpmKey is TPM_RH_NULL, this shall be the Empty Buffer.
    pub encryptedSalt: Vec<u8>,

    /// Indicates the type of the session; simple HMAC or policy (including a trial policy)
    pub sessionType: TPM_SE,

    /// The algorithm and key size for parameter encryption
    /// may select TPM_ALG_NULL
    pub symmetric: TPMT_SYM_DEF,

    /// Hash algorithm to use for the session
    /// Shall be a hash algorithm supported by the TPM and not TPM_ALG_NULL
    pub authHash: TPM_ALG_ID,
}

impl Default for TPM2_StartAuthSession_REQUEST {
    fn default() -> Self {
        Self {
            tpmKey: Default::default(),
            bind: Default::default(),
            nonceCaller: Default::default(),
            encryptedSalt: Default::default(),
            sessionType: Default::default(),
            symmetric: Default::default(),
            authHash: TPM_ALG_ID::NULL,
        }
    }
}

impl TPM2_StartAuthSession_REQUEST {
    /// Creates a new instance with the specified values
    pub fn new(
        tpmKey: &TPM_HANDLE,
        bind: &TPM_HANDLE,
        nonceCaller: &Vec<u8>,
        encryptedSalt: &Vec<u8>,
        sessionType: TPM_SE,
        symmetric: &TPMT_SYM_DEF,
        authHash: TPM_ALG_ID,
        ) -> Self {
        Self {
            tpmKey: tpmKey.clone(),
            bind: bind.clone(),
            nonceCaller: nonceCaller.clone(),
            encryptedSalt: encryptedSalt.clone(),
            sessionType: sessionType.clone(),
            symmetric: symmetric.clone(),
            authHash: authHash.clone(),
            ..Default::default()
        }
    }

}

impl TpmStructure for TPM2_StartAuthSession_REQUEST {
    // Implement serialization/deserialization
    fn serialize(&self, buf: &mut TpmBuffer) -> Result<(), TpmError> {
        // Serialize fields
        buf.writeSizedByteBuf(&self.nonceCaller, 2);
        buf.writeSizedByteBuf(&self.encryptedSalt, 2);
        buf.writeByte(self.sessionType.into());
        self.symmetric.toTpm(buf)?;
        buf.writeShort(self.authHash.into());
        Ok(())
    }

    fn deserialize(&mut self, buf: &mut TpmBuffer) -> Result<(), TpmError> {
        // Deserialize fields
        self.nonceCaller = buf.readSizedByteBuf(2);
        self.encryptedSalt = buf.readSizedByteBuf(2);
        self.sessionType = TPM_SE(buf.readByte() as u8);
        self.symmetric.initFromTpm(buf)?;
        self.authHash = TPM_ALG_ID(buf.readShort() as u16);
        Ok(())
    }

}

impl TpmMarshaller for TPM2_StartAuthSession_REQUEST {
    /// Serialize this structure to a TPM buffer
    fn toTpm(&self, buffer: &mut TpmBuffer) -> Result<(), TpmError> {
        self.serialize(buffer)
    }

    /// Deserialize this structure from a TPM buffer
    fn initFromTpm(&mut self, buffer: &mut TpmBuffer) -> Result<(), TpmError> {
        self.deserialize(buffer)
    }

}

impl CmdStructure for TPM2_StartAuthSession_REQUEST {
    fn num_handles(&self) -> u16 { 2 }

    fn sess_enc_info(&self) -> SessEncInfo { SessEncInfo { size_len: 2, val_len: 1 } }
}

impl ReqStructure for TPM2_StartAuthSession_REQUEST {
    fn num_auth_handles(&self) -> u16 { 0 }

    fn get_handles(&self) ->  Vec<TPM_HANDLE> { vec![self.tpmKey.clone(), self.bind.clone()] }
}

