/// The purpose of this command is to certify the contents of an NV Index or portion of an
/// NV Index.
#[derive(Debug, Clone, Default)]
pub struct TPM2_NV_Certify_REQUEST {
    /// Handle of the key used to sign the attestation structure
    /// Auth Index: 1
    /// Auth Role: USER
    pub signHandle: TPM_HANDLE,

    /// Handle indicating the source of the authorization value for the NV Index
    /// Auth Index: 2
    /// Auth Role: USER
    pub authHandle: TPM_HANDLE,

    /// Index for the area to be certified
    /// Auth Index: None
    pub nvIndex: TPM_HANDLE,

    /// User-provided qualifying data
    pub qualifyingData: Vec<u8>,

    /// Scheme selector

    /// Signing scheme to use if the scheme for signHandle is TPM_ALG_NULL
    /// One of: TPMS_SIG_SCHEME_RSASSA, TPMS_SIG_SCHEME_RSAPSS, TPMS_SIG_SCHEME_ECDSA,
    /// TPMS_SIG_SCHEME_ECDAA, TPMS_SIG_SCHEME_SM2, TPMS_SIG_SCHEME_ECSCHNORR,
    /// TPMS_SCHEME_HMAC, TPMS_SCHEME_HASH, TPMS_NULL_SIG_SCHEME.
    pub inScheme: Option<TPMU_SIG_SCHEME>,

    /// Number of octets to certify
    pub size: u16,

    /// Octet offset into the NV area
    /// This value shall be less than or equal to the size of the nvIndex data.
    pub offset: u16,
}

impl TPM2_NV_Certify_REQUEST {
    /// Creates a new instance with the specified values
    pub fn new(
        signHandle: &TPM_HANDLE,
        authHandle: &TPM_HANDLE,
        nvIndex: &TPM_HANDLE,
        qualifyingData: &Vec<u8>,
        inScheme: &Option<TPMU_SIG_SCHEME>,
        size: u16,
        offset: u16,
        ) -> Self {
        Self {
            signHandle: signHandle.clone(),
            authHandle: authHandle.clone(),
            nvIndex: nvIndex.clone(),
            qualifyingData: qualifyingData.clone(),
            inScheme: inScheme.clone(),
            size: size.clone(),
            offset: offset.clone(),
            ..Default::default()
        }
    }

}

impl TpmStructure for TPM2_NV_Certify_REQUEST {
    // Implement serialization/deserialization
    fn serialize(&self, buf: &mut TpmBuffer) -> Result<(), TpmError> {
        // Serialize fields
        buf.writeSizedByteBuf(&self.qualifyingData, 2);
        buf.writeShort(self.inScheme.as_ref().ok_or(TpmError::InvalidUnion)?.GetUnionSelector().into());
        self.inScheme.as_ref().ok_or(TpmError::InvalidUnion)?.toTpm(buf)?;
        buf.writeShort(self.size as u16);
        buf.writeShort(self.offset as u16);
        Ok(())
    }

    fn deserialize(&mut self, buf: &mut TpmBuffer) -> Result<(), TpmError> {
        // Deserialize fields
        self.qualifyingData = buf.readSizedByteBuf(2);
        let r#inSchemeScheme: TPM_ALG_ID = TPM_ALG_ID(buf.readShort() as u16);
        self.inScheme = TPMU_SIG_SCHEME::create(r#inSchemeScheme)?;
        self.inScheme.as_mut().ok_or(TpmError::InvalidUnion)?.initFromTpm(buf)?;
        self.size = buf.readShort() as u16;
        self.offset = buf.readShort() as u16;
        Ok(())
    }

}

